    def refine(self, s, coef, lo, hi, maximize):
        """Exact integer extremum inside [lo, hi] (inclusive)."""
        e = self.iv.expr(s, coef)
        if maximize:
            if lo == hi or self.check([e >= hi]):
                return hi
            a, b = lo, hi - 1
            while a < b:
                mid = (a + b + 1) // 2
                if self.check([e >= mid]):
                    a = mid
                else:
                    b = mid - 1
            return a
        else:
            if lo == hi or self.check([e <= lo]):
                return lo
            a, b = lo + 1, hi
            while a < b:
                mid = (a + b) // 2
                if self.check([e <= mid]):
                    b = mid
                else:
                    a = mid + 1
            return a

    def int_pair(self, s, coef):
        """Exact (min, max) of sum(coef*q[s]) over F.

        The rational relaxation supplies a tight candidate interval; the two
        guard checks below make the result depend only on satisfiability
        answers, never on the relaxation being solved correctly:  any value
        proved attainable outside the candidate interval widens it back to the
        demand box, and the binary search then proves the exact extremum.
        """
        key = (s, coef)
        hit = self.intcache.get(key)
        if hit is not None:
            return hit
        slo, shi = self.mdl.static_bounds(s, coef)
        if slo == shi:
            self.intcache[key] = (slo, slo)
            return (slo, slo)
        lmin, lmax = self.lp_pair(s, coef)
        relaxed = lmin is not None and lmax is not None
        if relaxed:
            a = max(slo, ceil_frac(lmin))
            b = min(shi, floor_frac(lmax))
            if a > b:
                a, b, relaxed = slo, shi, False
        else:
            a, b = slo, shi
        if self.out_of_time():
            # Safety valve: keep valid (possibly unattained) bounds.
            sys.stderr.write('deadline hit: loose bounds for objective\n')
            self.intcache[key] = (a, b)
            return (a, b)
        e = self.iv.expr(s, coef)
        if relaxed:
            if a > slo and self.check([e <= a - 1]):
                a = slo          # relaxation lower bound was not sound
            if b < shi and self.check([e >= b + 1]):
                b = shi          # relaxation upper bound was not sound
        lo = self.refine(s, coef, a, b, False)
        hi = self.refine(s, coef, a, b, True)
        self.intcache[key] = (lo, hi)
        return (lo, hi)

